    ) -> Result<(), Error> {
        let name = vm.try_intern(name.as_bytes())?;
        vm.call(
            vm.rooted(self.broadcast)?,
            &[
                name,
                Value::Boolean(params.is_some()),
                params.unwrap_or(Value::Nil),
                Value::Boolean(normalize),
            ],
        )?;
        Ok(())
    }

