/// Actual compiler output at the boundary after Update(0), before future probes.
pub struct LegacySongActivation {
    pub root: mlua::Table,
    pub tweens: std::collections::HashMap<usize, crate::rust_engine::SongStartupState>,
    pub initial_states: Vec<(mlua::Table, crate::SongLuaOverlayState)>,
    pub updates: std::collections::HashMap<usize, crate::rust_engine::SongStartupState>,
    pub broadcasts: Vec<(f32, String, bool)>,
    pub startup_queue: Vec<mlua::Table>,
    pub initialized_globals: [Option<mlua::Table>; 4],
    pub options: crate::SongLuaStartup,
    pub new_screen: Option<String>,
}
pub fn legacy_activate_song_layers(
    lua: &mlua::Lua,
    paths: &[&std::path::Path],
    primary: usize,
    context: &crate::SongLuaCompileContext,
) -> Result<LegacySongActivation, String> {
    lua.set_app_data(crate::compile::MigrationActivationProbe::default());
    lua.remove_app_data::<crate::compile::MigrationActivationResult>();
    let result = crate::compile::migration_compile_song_layers(lua, paths, primary, context);
    lua.remove_app_data::<crate::compile::MigrationActivationProbe>();
    let Some(output) = lua.remove_app_data::<crate::compile::MigrationActivationResult>() else {
        return Err(result
            .err()
            .unwrap_or_else(|| "activation boundary was not reached".into()));
    };
    let error = result.expect_err("phase observer must stop compiler");
    assert!(
        error.contains("migration activation boundary reached"),
        "{error}"
    );
    let tweens = if !context.live && output.new_screen.is_none() {
        crate::lua_util::migration_startup_tween_capture(&output.initial_states)?
    } else {
        Default::default()
    };
    Ok(LegacySongActivation {
        root: output.root,
        tweens,
        initial_states: output.initial_states,
        updates: output.updates,
        broadcasts: output.broadcasts,
        startup_queue: output.startup_queue,
        initialized_globals: output.initialized,
        options: output.options,
        new_screen: output.new_screen,
    })
}

