}

fn saved_pair(pair: &mut Pair, key: &str) -> (mlua::Table, deadlib_lua::TableId) {
    let source = format!("return saved.{key}");
    let native = pair.native.load(&source).eval().unwrap();
    let Value::Table(rust) = pair
        .rust
        .vm_mut()
        .execute(&compile_named(source.as_bytes(), b"=capture identity").unwrap())
        .unwrap()[0]
    else {
        panic!()
    };
    (native, rust)
}

#[test]
fn captured_initial_update_blocks_and_wrapper_defaults_match_compiler() {
    for live in [false, true] {
        let dir = tempfile::tempdir().unwrap();
        let path = write(
            dir.path(),
            "default.lua",
            r#"
            return Def.ActorFrame{
                InitCommand=function(self)saved.parent=self;self:x(4)end,
                OnCommand=function(self)
                    self:x(9):linear(2):x(40):queuecommand('Later')
                    saved.wrapper=self:AddWrapperState():x(19)
                    self:SetUpdateFunction(function(self)
                        self:x(50);saved.zero_wrapper=self:AddWrapperState():y(27)
                        collectgarbage()
                    end)
                end,
                LaterCommand=function()log('unexpected-future')end,
                Def.ActorFrame{
                    InitCommand=function(self)saved.child=self;self:y(3)end,
                    OnCommand=function(self)
                        self:y(8);self:SetUpdateFunction(function(self)self:y(12)end)
                    end,
                },
            }
        "#,
        );
        let mut context = SongLuaCompileContext::new(dir.path(), "startup capture");
        context.live = live;
        let mut pair = Pair::new(context);
        let (native, rust) = pair.activate(&[&path]);
        assert_eq!(rust.updates.len(), native.updates.len());
        assert_eq!(rust.tweens.len(), native.tweens.len());
        for key in ["parent", "child"] {
            let (a, b) = saved_pair(&mut pair, key);
            assert_eq!(
                rust.updates[&b],
                native.updates[&(a.to_pointer() as usize)],
                "{key}, live={live}"
            );
            if !live {
                assert_eq!(
                    rust.tweens[&b],
                    native.tweens[&(a.to_pointer() as usize)],
                    "startup tween {key}"
                );
            }
        }
        for key in ["wrapper", "zero_wrapper"] {
            let (a, b) = saved_pair(&mut pair, key);
            let expected = &native
                .initial_states
                .iter()
                .find(|(actor, _)| actor.to_pointer() == a.to_pointer())
                .unwrap()
                .1;
            assert_eq!(&rust.wrapper_initials[&b], expected, "{key}, live={live}");
            assert_eq!(expected, &deadsync_song_lua::SongLuaOverlayState::default());
            assert!(!rust.updates.contains_key(&b));
            if !live {
                assert_eq!(
                    rust.tweens[&b],
                    native.tweens[&(a.to_pointer() as usize)],
                    "wrapper tween {key}"
                );
            }
        }
        assert_eq!(rust.broadcasts, native.broadcasts, "live={live}");
    }
}

