    pair.script("events={}");
    let mut seconds = 0.;
    let mut owned = Vec::new();
    for (i, &dt) in deltas.iter().enumerate() {
        if i == 1 {
            pair.script("saved.armed=true");
        }
        seconds += dt;
        owned.extend(advance_predicted_frame(&mut pair, &native, i, seconds, dt));
    }
