type OutputKind =
    deadsync_song_lua::SongLuaOverlayKind<u32, u32, deadlib_present::actors::TextAttribute>;
fn output_kind_layer(slot: &u32) -> Option<deadsync_song_lua::SongLuaOverlayModelLayer<u32>> {
    (*slot != 0).then(|| {
        deadsync_song_lua::SongLuaOverlayModelLayer::new(
            std::sync::Arc::from("kind-model"),
            std::sync::Arc::from([*slot]),
            [2., 3.],
            [1.; 2],
            [0.; 2],
            [0.; 2],
            [0.; 2],
            None,
            deadsync_song_lua::SongLuaOverlayModelDraw::new(
                [0.; 3], [0.; 3], [1.; 3], [1.; 4], 0.5, false, true,
            ),
        )
    })
}
fn compare_kind_output(pair: &mut Pair, key: &str) -> Option<OutputKind> {
    let (native, rust) = saved_pair(pair, key);
    let class: String = native.raw_get("__songlua_actor_type").unwrap();
    let expected = test_support::legacy_read_song_overlay_kinds(
        &pair.native,
        native.clone(),
        &pair.context,
        |_, _, _| Ok(std::sync::Arc::from([7u32, 0u32])),
        output_kind_layer,
    )
    .unwrap();
    let expected = expected
        .iter()
        .find(|row| row.table.to_pointer() == native.to_pointer());
    let names = std::collections::HashSet::new();
    let initial = expected
        .map(|row| row.actor.initial_state)
        .unwrap_or_default();
    let actual = pair
        .rust
        .read_song_overlay_kind(
            Value::Table(rust),
            deadsync_song_lua::rust_engine::SongOverlayKindInputs {
                actor_type: &class,
                initial_state: initial,
                context: &pair.context,
                aft_capture_names: &names,
            },
            |_, _, _| Ok(std::sync::Arc::from([7u32, 0u32])),
            output_kind_layer,
        )
        .unwrap();
    assert_eq!(
        format!("{actual:?}"),
        format!("{:?}", expected.map(|row| &row.actor.kind)),
        "{key}"
    );
    pair.compare();
    actual
}

