crates/deadsync-song-lua/src/rust_engine.text:
//! Constructor and startup command capture, before compiler frame replay.
//! This is song-host scheduling state, not part of the Lua interpreter.
use super::*;
use crate::{SongLuaOverlayCommandBlock as Block, SongLuaOverlayStateDelta as Delta};

/// Owned command output and queue metadata for preparation/baking. These values
/// retain no Lua handles. Step zero denotes direct or immediate capture output.
#[derive(Clone, Debug, PartialEq)]
pub struct ActorCommandCapture {
    pub blocks: Vec<Block>,
    pub block_steps: Vec<usize>,
    /// A command occupies a zero-duration queue state, represented by None.
    pub steps: Vec<Option<f32>>,
    pub queued_commands: Vec<(Vec<u8>, f32)>,
}

#[derive(Clone)]
struct Entry {
    block: Block,
    tween_step: usize,
}

#[derive(Clone)]
struct Spin {
    current: [f32; 3],
    queued: bool,
}

#[derive(Clone, Default)]
pub(super) struct Capture {
    cursor: f32,
    pub(super) time_left: f32,
    current: Option<Entry>,
    blocks: Vec<Entry>,
    // Finish replaces the block list without replacing native's cached
    // immediate block. None as the index represents that detached block.
    immediate: Option<(f32, Option<usize>)>,
    steps: VecDeque<Option<f32>>,
    pending: VecDeque<(Vec<u8>, f32)>,
    /// A self-queue describes a repeating command; it must not recurse during
    /// discovery. Frame scheduling will consume this retained command later.
    pub(super) recurring: recurring::State,
    queue_error_reported: bool,
    active_start: f32,
    active_exact: f64,
    spin: Option<Spin>,
    deferred: bool,
}

fn block(start: f32, duration: f32, easing: Option<String>, queued: bool) -> Block {
    Block {
        progress: None,
        queued,
        start,
        duration,
        easing,
        opt1: None,
        opt2: None,
        delta: Delta::default(),
    }
}

impl Capture {
    pub(super) fn begin_discovery(&mut self) {
        self.flush();
        self.blocks.clear();
        self.immediate = None;
    }

    pub(super) fn snapshot(&mut self) -> ActorCommandCapture {
        let blocks = self.blocks();
        ActorCommandCapture {
            blocks,
            block_steps: self.blocks.iter().map(|entry| entry.tween_step).collect(),
            steps: self.steps.iter().copied().collect(),
            queued_commands: self.pending.iter().cloned().collect(),
        }
    }

    pub(super) fn cursor(&self) -> f32 {
        self.cursor
    }

    pub(super) fn pending_steps(&self) -> usize {
        self.steps.len()
    }

    fn scheduled(&self) -> bool {
        self.cursor.max(0.) > f32::EPSILON
            || self
                .current
                .as_ref()
                .is_some_and(|entry| entry.block.duration.max(0.) > f32::EPSILON)
    }

    fn cancel(&mut self, finish: bool) {
        self.flush();
        if finish {
            let mut delta = Delta::default();
            for entry in &self.blocks {
                crate::merge_overlay_delta(&mut delta, &entry.block.delta);
            }
            self.blocks.clear();
            if !crate::overlay_delta_is_empty(&delta) {
                let mut final_block = block(0., 0., None, false);
                final_block.delta = delta;
                self.blocks.push(Entry {
                    block: final_block,
                    tween_step: 0,
                });
            }
            self.immediate = self.immediate.map(|(start, _)| (start, None));
        } else {
            self.blocks
                .retain(|entry| entry.tween_step == 0 && entry.block.duration == 0.);
            self.immediate = None;
        }
        self.cursor = 0.;
        self.time_left = 0.;
        self.steps.clear();
        self.pending.clear();
        self.recurring.command = None;
        self.recurring.remaining = None;
        self.deferred = false;
    }

    pub(super) fn hurry(&mut self, factor: f32) {
        self.flush();
        for entry in &mut self.blocks {
            entry.block.start *= factor;
            entry.block.duration *= factor;
        }
        for seconds in self.steps.iter_mut().flatten() {
            *seconds *= factor;
        }
        self.cursor *= factor;
        self.time_left *= factor;
        self.active_exact *= f64::from(factor);
        if let Some(left) = &mut self.recurring.remaining {
            *left *= f64::from(factor);
        }
        if let Some((start, Some(_))) = &mut self.immediate {
            *start *= factor;
        }
        // Queue dispatch starts are separate from the scaled tween clocks;
        // the production constructor retains those original starts as well.
    }

    fn current(&mut self, queued: bool) -> &mut Entry {
        self.current.get_or_insert_with(|| Entry {
            block: block(self.cursor, 0., None, queued),
            tween_step: self.steps.len(),
        })
    }

    pub(super) fn flush(&mut self) {
        if let Some(entry) = self.current.take() {
            self.cursor = entry.block.start + entry.block.duration.max(0.);
            if !crate::overlay_delta_is_empty(&entry.block.delta) {
                self.blocks.push(entry);
            }
        }
    }

    pub(super) fn exact_step(&mut self, duration: f64) {
        self.active_exact += duration;
    }

    pub(super) fn reset_command(&mut self) {
        self.cursor = 0.;
        self.time_left = 0.;
        self.current = None;
        self.blocks.clear();
        self.immediate = None;
        self.steps.clear();
    }

    pub(super) fn begin_tween(&mut self, duration: f32, easing: &str, queued: bool) {
        self.flush();
        if let Some(spin) = &mut self.spin {
            spin.queued = true;
        }
        self.steps.push_back(Some(duration));
        self.time_left = self.cursor + duration;
        self.current = Some(Entry {
            block: block(self.cursor, duration, Some(easing.to_owned()), queued),
            tween_step: self.steps.len(),
        });
    }

    pub(super) fn write(&mut self, delta: Delta, immediate: bool, scope: Option<f32>) {
        let start = scope.unwrap_or(0.);
        let direct = start == 0.
            && self.cursor == 0.
            && self.current.as_ref().is_none_or(|c| c.block.duration == 0.)
            && self.steps.is_empty();
        let target = if !immediate || direct {
            &mut self.current(scope.is_some()).block.delta
        } else {
            let index = if let Some((_, index)) = self
                .immediate
                .filter(|(cached, _)| (*cached - start).abs() <= f32::EPSILON)
            {
                let Some(index) = index else { return };
                index
            } else {
                let index = self
                    .blocks
                    .iter()
                    .position(|entry| {
                        entry.block.start > start
                            || (entry.block.start == start
                                && (entry.tween_step > 0 || entry.block.duration > 0.))
                    })
                    .unwrap_or(self.blocks.len());
                self.blocks.insert(
                    index,
                    Entry {
                        block: block(start, 0., None, scope.is_some()),
                        tween_step: 0,
                    },
                );
                self.immediate = Some((start, Some(index)));
                index
            };
            &mut self.blocks[index].block.delta
        };
        crate::merge_overlay_delta(target, &delta);
    }

    pub(super) fn blocks(&mut self) -> Vec<Block> {
        self.flush();
        self.blocks
            .iter()
            .map(|entry| {
                let mut block = entry.block.clone();
                block.duration = block.duration.max(0.);
                block
            })
            .collect()
    }
}

pub(super) fn write(
    call: &mut HostCall<'_>,
    store: &Shared,
    id: TableId,
    delta: Delta,
    immediate: bool,
) {
    let mut guard = store.lock().unwrap();
    let scope = guard.capture_scope;
    let fallback = song_pose::mode(&guard, id);
    if let Some(actor) = guard.actors.get_mut(&id) {
        record(actor, &delta, immediate, scope, fallback);
    }
    drop(guard);
    if !song_pose::record(call, store, id, &delta) {
        song_messages::record(call, store, id, &delta);
    }
    song_immediate::delta(call, store, id, &delta, immediate);
    song_media::delta(call, store, id, &delta);
}

fn record(actor: &mut Actor, delta: &Delta, immediate: bool, scope: Option<f32>, fallback: bool) {
    if let Some(replay) = &mut actor.replay {
        for target in crate::tween_pose::TARGETS {
            if delta.has_update_target(target) {
                replay.targets |= 1u128 << target as usize;
            }
        }
    }
    if let Some(pose) = actor
        .replay
        .as_mut()
        .and_then(|replay| replay.getters.as_mut())
    {
        let mut state = crate::SongLuaOverlayState::default();
        pose.write_to(&mut state);
        crate::apply_overlay_delta(&mut state, delta);
        *pose = state.into();
    }
    if actor.replay.is_some() && !fallback {
        let current = actor.current;
        if let Some(getters) = &mut actor.preparation_getters {
            for ((getter, changed), value) in getters
                .iter_mut()
                .zip([delta.x, delta.y, delta.z, delta.aux])
                .zip([current.x, current.y, current.z, current.aux])
            {
                if changed.is_some() {
                    *getter = value;
                }
            }
        }
    }
    let Some(capture) = &mut actor.capture else {
        return;
    };
    if let Some(spin) = &mut capture.spin
        && !spin.queued
    {
        for (axis, value) in
            spin.current
                .iter_mut()
                .zip([delta.rot_x_deg, delta.rot_y_deg, delta.rot_z_deg])
        {
            if let Some(value) = value {
                *axis = value;
            }
        }
    }
    // Zero-duration construction steps do not defer current-position getters.
    // These fields are independent of the retained destination/spin queue.
    if !capture.scheduled() && !fallback {
        let values = [delta.x, delta.y, delta.z, delta.aux];
        if values.iter().any(Option::is_some) {
            let current = actor.current;
            let getters = actor.preparation_getters.get_or_insert([
                current.x,
                current.y,
                current.z,
                current.aux,
            ]);
            for (getter, value) in getters.iter_mut().zip(values) {
                if let Some(value) = value {
                    *getter = value;
                }
            }
        }
    }
    capture.write(*delta, immediate, scope);
}

pub(super) fn cancel(actor: &mut Actor, finish: bool) -> bool {
    if actor.capture.is_none() {
        return false;
    }
    let current = actor.current;
    let getters =
        actor
            .preparation_getters
            .unwrap_or([current.x, current.y, current.z, current.aux]);
    let mut dest = *actor.destination();
    if !finish {
        [dest.x, dest.y, dest.z] = [getters[0], getters[1], getters[2]];
    }
    if let Some(spin) = &mut actor.capture.as_mut().unwrap().spin {
        if finish {
            spin.current = [dest.rot_x_deg, dest.rot_y_deg, dest.rot_z_deg];
        }
        [dest.rot_x_deg, dest.rot_y_deg, dest.rot_z_deg] = spin.current;
        spin.queued = false;
    }
    actor.capture.as_mut().unwrap().cancel(finish);
    actor.current = dest;
    actor.queue.clear();
    actor.sync_rotation_getters();
    actor.preparation_getters = Some(getters);
    true
}

pub(super) fn start_spin(actor: &mut Actor) {
    let pose = *actor.destination();
    if let Some(capture) = &mut actor.capture {
        capture.spin.get_or_insert(Spin {
            current: [pose.rot_x_deg, pose.rot_y_deg, pose.rot_z_deg],
            queued: false,
        });
    }
}

/// Record an actual successful write, including writes equal to the old value.
/// Comparing snapshots would lose those writes and change later composition.
pub(super) fn property(call: &mut HostCall<'_>, store: &Shared, id: TableId, name: &str) {
    let mut guard = store.lock().unwrap();
    let fallback = song_pose::mode(&guard, id);
    let scope = guard.capture_scope;
    let immediate_visibility = scope.is_some()
        || guard.startup_queues.is_some()
        || guard.startup_discovery
        || guard.replay_frame.is_some();
    let actor = guard.actors.get_mut(&id).unwrap();
    if actor.capture.is_none() && actor.replay.is_none() {
        return;
    }
    let pose = actor.destination();
    let state = &actor.state;
    let render = &state.render;
    let mut delta = Delta::default();
    let mut immediate = false;
    match name {
        "x" | "addx" | "CenterX" => delta.x = Some(pose.x),
        "y" | "addy" | "CenterY" => delta.y = Some(pose.y),
        "z" | "addz" => delta.z = Some(pose.z),
        "Center" => {
            delta.x = Some(pose.x);
            delta.y = Some(pose.y);
        }
        "zoom" => {
            delta.zoom = Some(pose.zoom);
            delta.zoom_x = Some(pose.zoom_x);
            delta.zoom_y = Some(pose.zoom_y);
            delta.zoom_z = Some(pose.zoom_z);
        }
        "zoomx" | "zoomtowidth" => delta.zoom_x = Some(pose.zoom_x),
        "zoomy" | "zoomtoheight" => delta.zoom_y = Some(pose.zoom_y),
        "zoomz" => delta.zoom_z = Some(pose.zoom_z),
        "zoomto" => {
            delta.zoom_x = Some(pose.zoom_x);
            delta.zoom_y = Some(pose.zoom_y);
        }
        "stretchto" => {
            delta.x = Some(pose.x);
            delta.y = Some(pose.y);
            delta.zoom_x = Some(pose.zoom_x);
            delta.zoom_y = Some(pose.zoom_y);
        }
        "rotationx" | "addrotationx" => delta.rot_x_deg = Some(pose.rot_x_deg),
        "rotationy" | "addrotationy" => delta.rot_y_deg = Some(pose.rot_y_deg),
        "rotationz" | "addrotationz" => delta.rot_z_deg = Some(pose.rot_z_deg),
        "aux" => delta.aux = Some(pose.aux),
        "visible" => {
            delta.visible = Some(state.visible);
            immediate = immediate_visibility;
        }
        "draworder" => delta.draw_order = Some(state.draw_order),
        "size" | "SetWidth" | "SetHeight" | "setsize" => {
            delta.size = Some(state.size);
            immediate = true;
        }
        "diffuse" | "diffusecolor" | "diffusealpha" => delta.diffuse = Some(pose.diffuse),
        "glow" => delta.glow = Some(pose.glow),
        "vertex_colors" => delta.vertex_colors = pose.vertex_colors,
        "cropleft" => delta.cropleft = Some(pose.cropleft),
        "cropright" => delta.cropright = Some(pose.cropright),
        "croptop" => delta.croptop = Some(pose.croptop),
        "cropbottom" => delta.cropbottom = Some(pose.cropbottom),
        "fadeleft" => delta.fadeleft = Some(pose.fadeleft),
        "faderight" => delta.faderight = Some(pose.faderight),
        "fadetop" => delta.fadetop = Some(pose.fadetop),
        "fadebottom" => delta.fadebottom = Some(pose.fadebottom),
        "skewx" => delta.skew_x = Some(pose.skew_x),
        "skewy" => delta.skew_y = Some(pose.skew_y),
        "heading" | "pitch" | "roll" => delta.quaternion = Some(pose.quaternion),
        "halign" => {
            delta.halign = Some(render.halign);
            immediate = true;
        }
        "valign" => {
            delta.valign = Some(render.valign);
            immediate = true;
        }
        // Immediate renderer/base-transform properties do not join a tween.
        "basealpha" => {
            delta.base_alpha = Some(render.base_alpha);
            immediate = true;
        }
        "basezoom" => {
            delta.basezoom = Some(render.basezoom);
            delta.basezoom_x = Some(render.basezoom_x);
            delta.basezoom_y = Some(render.basezoom_y);
            delta.basezoom_z = Some(render.basezoom_z);
            immediate = true;
        }
        "basezoomx" => {
            delta.basezoom_x = Some(render.basezoom_x);
            immediate = true;
        }
        "basezoomy" => {
            delta.basezoom_y = Some(render.basezoom_y);
            immediate = true;
        }
        "basezoomz" => {
            delta.basezoom_z = Some(render.basezoom_z);
            immediate = true;
        }
        "baserotationx" | "baserotationy" | "baserotationz" => {
            delta.base_rotation = Some(render.base_rotation);
            immediate = true;
        }
        "shadowlength" | "shadowlengthx" | "shadowlengthy" => {
            delta.shadow_len = Some(render.shadow_len);
            immediate = true;
        }
        "shadowcolor" => {
            delta.shadow_color = Some(render.shadow_color);
            immediate = true;
        }
        "zbias" => {
            delta.z_bias = Some(render.z_bias);
            immediate = true;
        }
        "fov" => {
            delta.fov = render.fov;
            immediate = true;
        }
        _ => return,
    }
    record(actor, &delta, immediate, scope, fallback);
    drop(guard);
    if !song_pose::record(call, store, id, &delta) {
        song_messages::record(call, store, id, &delta);
    }
    song_immediate::delta(call, store, id, &delta, immediate);
    song_media::delta(call, store, id, &delta);
}

// Once a fallback actor queues during an update, that queue belongs to frame
// advancement. Captured commands outside the update instead drain synchronously.
pub(super) fn enter_replay_queue(store: &Shared, actor: TableId) {
    let mut guard = store.lock().unwrap();
    // Full-timeline preparation retains its fallback capture and command queue.
    // Streamed preparation continues to use the ordinary queue below.
    if guard.replay_clock.is_some() {
        return;
    }
    if guard.replay_frame.is_some() && guard.replay_advancing {
        let actor = guard.actors.get_mut(&actor).unwrap();
        if actor
            .capture
            .as_ref()
            .is_some_and(|c| c.recurring.command.is_some() || c.recurring.running)
        {
            return;
        }
        if actor.capture.take().is_some() {
            // Captured steps have already emitted their timed publications.
            // The first update-created queue starts its own clock; those old
            // durations must not postpone commands queued by this callback.
            actor.queue.clear();
        }
    }
}

pub(super) fn queue(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: Vec<u8>,
) -> Result<bool, Error> {
    enter_replay_queue(store, actor);
    let mut command_field = name.clone();
    command_field.extend_from_slice(b"Command");
    let overflow = {
        let guard = store.lock().unwrap();
        let target = &guard.actors[&actor];
        !target.active_commands.contains(&command_field)
            && target.capture.as_ref().is_some_and(|capture| {
                guard
                    .replay_clock
                    .as_ref()
                    .and_then(|clock| clock.queue_len(actor))
                    .unwrap_or_else(|| capture.pending_steps())
                    > 50
            })
    };
    if overflow {
        lifecycle::finish(call, store, actor)?;
    }
    let full_capture = {
        let guard = store.lock().unwrap();
        guard.replay_clock.is_some() && guard.actors[&actor].capture.is_some()
    };
    if full_capture {
        song_messages::timing(call, actor, 0., None)?;
    }
    let drain = {
        let mut guard = store.lock().unwrap();
        let startup = guard.startup_queues.is_some();
        let self_queue = guard.actors[&actor]
            .active_commands
            .contains(&command_field);
        if guard.actors[&actor].capture.is_some()
            && let Some(clock) = &mut guard.replay_clock
        {
            if self_queue {
                clock.flush(actor);
            } else {
                clock.tween(actor, None);
            }
        }
        let actor = guard.actors.get_mut(&actor).unwrap();
        let Some(capture) = &mut actor.capture else {
            return Ok(false);
        };
        capture.flush();
        let mut field = name.clone();
        field.extend_from_slice(b"Command");
        if actor.active_commands.contains(&field) {
            let interval = if capture.active_exact > f64::EPSILON {
                capture.active_exact
            } else {
                f64::from((capture.cursor - capture.active_start).max(0.))
            };
            capture.recurring.command = Some(name);
            if interval > f64::EPSILON {
                capture.recurring.interval = interval;
            }
            return Ok(true);
        }
        capture.steps.push_back(None);
        capture.pending.push_back((name, capture.cursor));
        startup || actor.active_commands.is_empty()
    };
    if store.lock().unwrap().replay_frame.is_some() {
        song_messages::timing(call, actor, 0., None)?;
    }
    if drain {
        drain_commands(call, store, actor)?;
    }
    Ok(true)
}

pub(super) fn advance_ready(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
) -> Result<(), Error> {
    let ready = {
        let guard = store.lock().unwrap();
        guard.actors[&actor].registered
            && guard
                .replay_clock
                .as_ref()
                .is_some_and(|clock| clock.ready(actor))
    };
    if !ready {
        return Ok(());
    }
    match drain_commands(call, store, actor) {
        Err(error) if error.kind() == ErrorKind::Runtime => {
            let mut guard = store.lock().unwrap();
            let Some(capture) = guard
                .actors
                .get_mut(&actor)
                .and_then(|a| a.capture.as_mut())
            else {
                return Ok(());
            };
            if !capture.queue_error_reported {
                capture.queue_error_reported = true;
                guard.diagnostics.push(format!("update queue: {error}"));
            }
            Ok(())
        }
        result => result,
    }
}

pub(super) fn drain_commands(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
) -> Result<(), Error> {
    {
        let mut guard = store.lock().unwrap();
        let pending = guard
            .actors
            .get(&actor)
            .and_then(|actor| actor.capture.as_ref())
            .is_some_and(|capture| !capture.pending.is_empty());
        if let Some(queued) = &mut guard.startup_queues {
            if pending && !queued.contains(&actor) {
                queued.push(actor);
            }
            return Ok(());
        }
    }
    loop {
        let (next, clock_time) = {
            let mut guard = store.lock().unwrap();
            if !guard
                .actors
                .get(&actor)
                .and_then(|a| a.capture.as_ref())
                .is_some_and(|c| !c.pending.is_empty())
            {
                return Ok(());
            }
            let mut time = None;
            if let Some(clock) = &mut guard.replay_clock {
                clock.prime(actor);
                if clock.waiting(actor) {
                    return Ok(());
                }
                time = clock.pending_dispatch(actor);
            }
            let discovery = guard.startup_discovery;
            let full = guard.replay_clock.is_some();
            let capture = guard
                .actors
                .get_mut(&actor)
                .unwrap()
                .capture
                .as_mut()
                .unwrap();
            let (name, start) = capture.pending.front().unwrap();
            if !full && (discovery || capture.deferred) && (name.starts_with(b"!") || *start > 0.) {
                capture.deferred = true;
                return Ok(());
            }
            let next = capture.pending.pop_front().unwrap();
            while let Some(step) = capture.steps.pop_front() {
                if step.is_none() {
                    break;
                }
            }
            (next, time)
        };
        let (name, captured_start) = next;
        let start = if clock_time.is_some() {
            0.
        } else {
            captured_start
        };
        let (prior, previous_dispatch, previous_clock, was_recurring, remainder, cursor) = {
            let mut guard = store.lock().unwrap();
            let mut previous_clock = guard.replay_clock.as_ref().and_then(|c| c.dispatch);
            let mut seconds = None;
            let mut cursor = None;
            if let Some(clock) = &mut guard.replay_clock {
                if clock_time.is_some() {
                    previous_clock = clock.dispatched(actor, 0.);
                    seconds = clock.dispatch.map(|scope| clock.time(scope.frame));
                    cursor = Some(clock.cursor(actor));
                } else {
                    clock.dispatch = None;
                }
            }
            let capture = guard
                .actors
                .get_mut(&actor)
                .unwrap()
                .capture
                .as_mut()
                .unwrap();
            if let Some(cursor) = cursor {
                capture.flush();
                capture.cursor = cursor;
            }
            let was_recurring = capture.recurring.command.is_some();
            let prior = guard.capture_scope.replace(start);
            let dispatch = guard.replay_dispatch;
            if guard.replay_frame.is_some() {
                guard.replay_dispatch = Some(song_immediate::Dispatch {
                    seconds,
                    delay: start,
                });
            }
            (
                prior,
                dispatch,
                previous_clock,
                was_recurring,
                clock_time.map(|t| t.1 as f32),
                cursor,
            )
        };
        if let Some(cursor) = cursor {
            let result = (|| {
                song_messages::timing(call, actor, 0., None)?;
                song_replay::raw_set(
                    call,
                    actor,
                    "__songlua_capture_cursor",
                    Value::Number(f64::from(cursor)),
                )
            })();
            if let Err(error) = result {
                let mut guard = store.lock().unwrap();
                guard.capture_scope = prior;
                guard.replay_dispatch = previous_dispatch;
                if let Some(clock) = &mut guard.replay_clock {
                    clock.dispatch = previous_clock;
                }
                return Err(error);
            }
        }
        // The registry and this lexical root retain the dispatch target even
        // when its command edits the scene and forces a collection.
        let result = call.with_roots(&[Value::Table(actor)], |call| {
            if let Some(message) = name.strip_prefix(b"!") {
                messages::queued(call, store, message)
            } else {
                let mut field = name.clone();
                field.extend_from_slice(b"Command");
                let previous = store
                    .lock()
                    .unwrap()
                    .actors
                    .get_mut(&actor)
                    .unwrap()
                    .active_commands
                    .remove(&field);
                let result = dispatch(call, store, actor, &name);
                if previous {
                    store
                        .lock()
                        .unwrap()
                        .actors
                        .get_mut(&actor)
                        .unwrap()
                        .active_commands
                        .insert(field);
                }
                result
            }
        });
        {
            let mut guard = store.lock().unwrap();
            guard.capture_scope = prior;
            guard.replay_dispatch = previous_dispatch;
            if let Some(clock) = &mut guard.replay_clock {
                clock.dispatch = previous_clock;
            }
        }
        result?;
        song_pose::advance_position(call, store, actor)?;
        let recurring = store
            .lock()
            .unwrap()
            .actors
            .get(&actor)
            .and_then(|a| a.capture.as_ref())
            .is_some_and(|c| c.recurring.command.is_some());
        if !was_recurring
            && recurring
            && let Some(remainder) = remainder
        {
            recurring::advance(call, store, actor, remainder)?;
            if let Some(clock) = &mut store.lock().unwrap().replay_clock {
                clock.mark_recurring(actor);
            }
        }
    }
}

fn dispatch(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &[u8],
) -> Result<(), Error> {
    {
        let mut guard = store.lock().unwrap();
        let start = guard.capture_scope.unwrap_or(0.);
        if let Some(capture) = guard
            .actors
            .get_mut(&actor)
            .and_then(|a| a.capture.as_mut())
            && capture.cursor < start
        {
            capture.flush();
            capture.cursor = start;
        }
    }
    native_children::run_command(call, store, actor, name, None)?;
    let kind = sprites::field(call, actor, "__songlua_actor_type")?;
    if matches!(kind, Value::String(id) if matches!(call.string_bytes(id), Some(b"ActorFrame" | b"ActorFrameTexture" | b"TopScreen")))
    {
        native_children::with_children(call, actor, |call, child| {
            dispatch(call, store, child, name)
        })?;
    }
    Ok(())
}

pub(super) fn command_start(store: &Shared, actor: TableId) -> Option<(f32, f64)> {
    let mut guard = store.lock().unwrap();
    let capture = guard.actors.get_mut(&actor)?.capture.as_mut()?;
    Some((
        std::mem::replace(&mut capture.active_start, capture.cursor),
        std::mem::take(&mut capture.active_exact),
    ))
}

pub(super) fn command_end(store: &Shared, actor: TableId, previous: Option<(f32, f64)>) {
    if let Some(previous) = previous
        && let Some(capture) = store
            .lock()
            .unwrap()
            .actors
            .get_mut(&actor)
            .and_then(|a| a.capture.as_mut())
    {
        (capture.active_start, capture.active_exact) = previous;
    }
}

impl Actors {
    pub(in crate::rust_engine) fn begin_preparation(&self, vm: &mut Vm) -> Result<bool, Error> {
        {
            let guard = self.store.lock().unwrap();
            if guard.preparing
                || guard.playback
                || guard.clock.live.load(std::sync::atomic::Ordering::Relaxed)
            {
                return Ok(false);
            }
        }
        let function = vm.rooted(self.prepare_definitions)?;
        vm.call(function, &[])?;
        let mut guard = self.store.lock().unwrap();
        guard.preparing = true;
        guard.constructing_capture = true;
        Ok(true)
    }

    pub(in crate::rust_engine) fn discover_startup(&self, vm: &mut Vm) -> Result<(), Error> {
        let function = vm.rooted(self.discover_startup)?;
        vm.call(function, &[])?;
        Ok(())
    }

    pub(super) fn discover_queued(&self, vm: &mut Vm, queued: Vec<TableId>) -> Result<(), Error> {
        let mut roots = vec![Value::Table(self.registry), Value::Table(self.helpers)];
        roots.extend(queued.iter().copied().map(Value::Table));
        let function = vm.new_host_function_with_data(
            |call| {
                let (store, queued) = call
                    .function_data::<(Shared, Vec<TableId>)>()
                    .unwrap()
                    .clone();
                run_discovery(call, &store, queued)
            },
            &roots,
            (self.store.clone(), queued),
        )?;
        vm.call(function, &[])?;
        Ok(())
    }

    pub(in crate::rust_engine) fn command_capture(
        &self,
        actor: Value,
    ) -> Option<ActorCommandCapture> {
        let Value::Table(actor) = actor else {
            return None;
        };
        let mut guard = self.store.lock().unwrap();
        let capture = guard.actors.get_mut(&actor)?.capture.as_mut()?;
        Some(capture.snapshot())
    }

    pub(in crate::rust_engine) fn captured_blocks(&self, actor: Value) -> Option<Vec<Block>> {
        let Value::Table(actor) = actor else {
            return None;
        };
        let mut guard = self.store.lock().unwrap();
        Some(guard.actors.get_mut(&actor)?.capture.as_mut()?.blocks())
    }
}

pub(super) fn discover_startup(call: &mut HostCall<'_>, store: &Shared) -> Result<(), Error> {
    let queued = store.lock().unwrap().startup_queues.take();
    let Some(queued) = queued else {
        return Ok(());
    };
    run_discovery(call, store, queued)
}

fn run_discovery(
    call: &mut HostCall<'_>,
    store: &Shared,
    queued: Vec<TableId>,
) -> Result<(), Error> {
    let previous = std::mem::replace(&mut store.lock().unwrap().startup_discovery, true);
    let roots = queued.iter().copied().map(Value::Table).collect::<Vec<_>>();
    let result = call.with_roots(&roots, |call| {
        for actor in queued {
            drain_commands(call, store, actor)?;
        }
        Ok(())
    });
    store.lock().unwrap().startup_discovery = previous;
    result
}

//! Native actor effect selection, phase and spin, before tween advancement.
use super::{Actor, Shared, arg, float_scalar, helper, render, table};
use crate::{SongLuaOverlayState, SongLuaOverlayUpdateTarget as Target, rust_engine::Clock};
use deadlib_lua::{Error, HostCall, TableId, Value};
use deadlib_present::anim::{EffectClock, EffectMode};
use std::sync::atomic::Ordering;

pub(super) const METHODS: &[&str] = &[
    "diffuseblink",
    "diffuseshift",
    "diffuseramp",
    "glowblink",
    "glowshift",
    "glowramp",
    "rainbow",
    "wag",
    "bounce",
    "bob",
    "pulse",
    "spin",
    "vibrate",
    "stopeffect",
    "effectcolor1",
    "effectcolor2",
    "effectperiod",
    "effecttiming",
    "effect_hold_at_full",
    "effectoffset",
    "effectclock",
    "effectmagnitude",
    "geteffectmagnitude",
    "GetSecsIntoEffect",
    "GetEffectDelta",
];

#[derive(Clone, Copy, Default)]
pub(super) struct State {
    // None preserves getters' runtime-clock fallback before the first update.
    motion: Option<Motion>,
    spin_seen: bool,
    pub(super) spin_baked: bool,
}

#[derive(Clone, Copy, Default)]
struct Motion {
    // A failed first external-clock read leaves the clock created but without
    // units, as in the production host. Its delta getter still defaults to zero.
    units: Option<f32>,
    delta: f32,
}

fn set_period(render: &mut SongLuaOverlayState, period: f32) {
    render.effect_period = period;
    if render.effect_timing.is_some() {
        render.effect_timing = Some([period / 2.0, 0.0, period / 2.0, 0.0, 0.0]);
    }
}

fn select(actor: &mut Actor, name: &str) -> smallvec::SmallVec<[Target; 8]> {
    let mut fields = smallvec::smallvec![Target::Vibrate, Target::Rainbow, Target::EffectMode];
    if name == "spin" {
        super::capture::start_spin(actor);
    }
    let render = &mut actor.state.render;
    let mode = crate::parse_overlay_effect_mode(name).unwrap_or(EffectMode::None);
    let motion = matches!(name, "bob" | "bounce" | "wag");
    let color = matches!(
        name,
        "diffuseblink" | "diffuseshift" | "diffuseramp" | "glowblink" | "glowshift" | "glowramp"
    );
    let reset = (motion
        && (name == "bounce"
            || mode != render.effect_mode
            || (name == "bob" && render.effect_period != 2.0)))
        || (color && mode != render.effect_mode)
        || (name == "rainbow" && !render.rainbow);
    if motion || color || matches!(name, "pulse" | "rainbow") {
        let clock = actor.effects.motion.get_or_insert(Motion {
            units: Some(0.0),
            delta: 0.0,
        });
        if reset {
            clock.units = Some(0.0);
        }
    }
    render.effect_mode = mode;
    render.vibrate = name == "vibrate";
    render.rainbow = name == "rainbow";
    match name {
        "glowblink" | "glowshift" | "glowramp" => {
            set_period(render, 1.0);
            fields.push(Target::EffectPeriod);
            if render.effect_timing.is_some() {
                fields.push(Target::EffectTiming);
            }
            fields.extend([Target::EffectColor1, Target::EffectColor2]);
            render.effect_color1 = [1.0, 1.0, 1.0, 0.2];
            render.effect_color2 = [1.0, 1.0, 1.0, 0.8];
        }
        "diffuseblink" | "diffuseshift" | "diffuseramp" => {
            set_period(render, 1.0);
            fields.push(Target::EffectPeriod);
            if render.effect_timing.is_some() {
                fields.push(Target::EffectTiming);
            }
            fields.extend([Target::EffectColor1, Target::EffectColor2]);
            render.effect_color1 = if name == "diffuseblink" {
                [0.5; 4]
            } else {
                [0.0, 0.0, 0.0, 1.0]
            };
            render.effect_color2 = [1.0; 4];
        }
        "bob" | "bounce" | "wag" | "pulse" => {
            if name != "bob" || reset {
                set_period(render, 2.0);
                fields.push(Target::EffectPeriod);
                if render.effect_timing.is_some() {
                    fields.push(Target::EffectTiming);
                }
            }
            fields.push(Target::EffectMagnitude);
            render.effect_magnitude = match name {
                "pulse" => [0.5, 1.0, 1.0],
                "wag" => [0.0, 0.0, 20.0],
                _ => [0.0, 20.0, 0.0],
            };
        }
        "rainbow" => {
            set_period(render, 2.0);
            fields.push(Target::EffectPeriod);
            if render.effect_timing.is_some() {
                fields.push(Target::EffectTiming);
            }
        }
        "spin" => {
            fields.push(Target::EffectMagnitude);
            actor.effects.spin_seen = true;
            render.effect_magnitude = [0.0, 0.0, 180.0];
        }
        "vibrate" => {
            fields.push(Target::EffectMagnitude);
            render.effect_magnitude = [10.0; 3];
        }
        _ => {}
    }
    fields
}

fn number(call: &mut HostCall<'_>, value: Value) -> Result<f64, Error> {
    if let Value::Number(value) = value {
        return Ok(value);
    }
    match call.call(helper(call, 6)?, &[value])?[0] {
        Value::Number(value) => Ok(value),
        _ => Err(call.error(b"number expected")),
    }
}

fn field(call: &mut HostCall<'_>, runtime: Value, key: &str) -> Result<f64, Error> {
    let key = call.try_intern(key.as_bytes())?;
    let value = call.table_get(runtime, key)?;
    number(call, value)
}

fn runtime<T>(
    call: &mut HostCall<'_>,
    read: impl FnOnce(&mut HostCall<'_>, Value) -> Result<T, Error>,
) -> Result<T, Error> {
    let key = call.try_intern(crate::SONG_LUA_RUNTIME_KEY.as_bytes())?;
    let runtime = call.table_get(helper(call, 5)?, key)?;
    table(call, runtime)?;
    // A global __index may synthesize a table that detaches itself and collects
    // while a later field is read. Root the selected table for the whole read.
    call.with_roots(&[runtime], |call| read(call, runtime))
}

pub(super) fn values(call: &mut HostCall<'_>, delta: bool) -> Result<[f32; 2], Error> {
    runtime(call, |call, runtime| {
        let (beat, seconds) = if delta {
            (
                crate::SONG_LUA_RUNTIME_DELTA_BEAT_KEY,
                crate::SONG_LUA_RUNTIME_DELTA_SECONDS_KEY,
            )
        } else {
            (
                crate::SONG_LUA_RUNTIME_BEAT_KEY,
                crate::SONG_LUA_RUNTIME_SECONDS_KEY,
            )
        };
        Ok([
            field(call, runtime, beat)? as f32,
            field(call, runtime, seconds)? as f32,
        ])
    })
}

fn music(call: &mut HostCall<'_>, clock: &Clock) -> Result<f32, Error> {
    runtime(call, |call, runtime| {
        let seconds = field(call, runtime, crate::SONG_LUA_RUNTIME_SECONDS_KEY)?;
        let rate = field(call, runtime, crate::SONG_LUA_RUNTIME_RATE_KEY)? as f32;
        let seconds = if clock.live.load(Ordering::Relaxed) {
            seconds as f32
        } else {
            (seconds * f64::from(rate)) as f32
                + clock
                    .timing
                    .as_ref()
                    .map_or(0.0, |clock| clock.get_time_for_beat_exact(0.0))
        };
        // Preserve the production integer-valued-float path (notably -0).
        Ok(if seconds.fract() == 0.0 && seconds.abs() < 1e14 {
            (seconds as i64) as f32
        } else {
            seconds
        })
    })
}

pub(super) fn method(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &str,
) -> Result<(), Error> {
    let value = arg(call, 1);
    let mut fields = smallvec::SmallVec::<[Target; 8]>::new();
    match name {
        "GetSecsIntoEffect" | "GetEffectDelta" => {
            let (state, clock) = {
                let store = store.lock().unwrap();
                let actor = &store.actors[&actor];
                (actor.effects, actor.state.render.effect_clock)
            };
            let delta = name == "GetEffectDelta";
            let value = match state.motion {
                Some(motion) if delta => motion.delta,
                Some(motion) => motion
                    .units
                    .ok_or_else(|| call.error(b"effect clock has no units"))?,
                None => values(call, delta)?[usize::from(clock == EffectClock::Time)],
            };
            return call.push(Value::Number(value as f64));
        }
        "geteffectmagnitude" => {
            let values = store.lock().unwrap().actors[&actor]
                .state
                .render
                .effect_magnitude;
            for value in values {
                call.push(Value::Number(value as f64))?;
            }
            return Ok(());
        }
        "effectcolor1" | "effectcolor2" => {
            let color = render::color(call)?.unwrap_or([1.0; 4]);
            let mut store = store.lock().unwrap();
            let render = &mut store.actors.get_mut(&actor).unwrap().state.render;
            if name == "effectcolor1" {
                render.effect_color1 = color;
                fields.push(Target::EffectColor1);
            } else {
                render.effect_color2 = color;
                fields.push(Target::EffectColor2);
            }
        }
        "effectperiod" | "effectoffset" => {
            if let Some(value) = float_scalar(call, value, false) {
                let mut store = store.lock().unwrap();
                let render = &mut store.actors.get_mut(&actor).unwrap().state.render;
                if name == "effectperiod" {
                    set_period(render, value);
                    fields.push(Target::EffectPeriod);
                    if render.effect_timing.is_some() {
                        fields.push(Target::EffectTiming);
                    }
                } else {
                    render.effect_offset = value;
                    fields.push(Target::EffectOffset);
                }
            }
        }
        "effectmagnitude" => {
            let magnitude =
                [1, 2, 3].map(|i| float_scalar(call, arg(call, i), false).unwrap_or(0.0));
            store
                .lock()
                .unwrap()
                .actors
                .get_mut(&actor)
                .unwrap()
                .state
                .render
                .effect_magnitude = magnitude;
            fields.push(Target::EffectMagnitude);
        }
        "effecttiming" => {
            let mut timing = [0.0; 5];
            for (i, index) in [0, 1, 2, 4].into_iter().enumerate() {
                let Some(value) = float_scalar(call, arg(call, i + 1), false) else {
                    return call.push(Value::Table(actor));
                };
                timing[index] = value.max(0.0);
            }
            timing[3] = float_scalar(call, arg(call, 5), false)
                .unwrap_or(0.0)
                .max(0.0);
            let total = timing.iter().sum::<f32>();
            if total > 0.0 {
                let mut store = store.lock().unwrap();
                let render = &mut store.actors.get_mut(&actor).unwrap().state.render;
                render.effect_timing = Some(timing);
                render.effect_period = total;
                fields.extend([Target::EffectTiming, Target::EffectPeriod]);
            }
        }
        "effect_hold_at_full" => {
            let hold = number(call, value)? as f32;
            let mut store = store.lock().unwrap();
            let render = &mut store.actors.get_mut(&actor).unwrap().state.render;
            let period = render.effect_period;
            let mut timing =
                render
                    .effect_timing
                    .unwrap_or([period / 2.0, 0.0, period / 2.0, 0.0, 0.0]);
            timing[3] = hold;
            let total = timing.iter().sum::<f32>();
            if hold < 0.0 || total <= 0.0 {
                return Err(call.error(b"effect timings must be nonnegative and not all zero"));
            }
            render.effect_timing = Some(timing);
            render.effect_period = total;
            fields.extend([Target::EffectTiming, Target::EffectPeriod]);
        }
        "effectclock" => {
            if let Some(raw) = render::text(call, value)
                && let Some(clock) = crate::parse_overlay_effect_clock(raw)
            {
                let mut store = store.lock().unwrap();
                let render = &mut store.actors.get_mut(&actor).unwrap().state.render;
                render.effect_clock = clock;
                render.effect_no_offset = raw.eq_ignore_ascii_case("beatnooffset");
                render.effect_timer = raw.eq_ignore_ascii_case("timer");
                fields.extend([
                    Target::EffectClock,
                    Target::EffectNoOffset,
                    Target::EffectTimer,
                ]);
            }
        }
        _ => fields = select(store.lock().unwrap().actors.get_mut(&actor).unwrap(), name),
    }
    if !fields.is_empty() {
        let state = store.lock().unwrap().actors[&actor].state.render;
        for target in fields {
            super::song_immediate::record(
                call,
                store,
                actor,
                target,
                crate::perframe::overlay_state_update_value(&state, target),
            );
        }
    }
    call.push(Value::Table(actor))
}

pub(super) fn advance(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    delta: f32,
) -> Result<(), Error> {
    let (previous, render, clock) = {
        let mut store = store.lock().unwrap();
        let clock = store.clock.clone();
        let actor = store.actors.get_mut(&actor).unwrap();
        let previous = actor
            .effects
            .motion
            .get_or_insert_with(Motion::default)
            .units
            .unwrap_or(0.0);
        (previous, actor.state.render, clock)
    };
    let (units, elapsed) = if render.effect_timer {
        let mut units = previous + delta;
        // Native Actor subtracts once, with strict >, rather than modulo.
        if units > render.effect_period {
            units -= render.effect_period;
        }
        (units, delta)
    } else {
        let units = if render.effect_clock == EffectClock::Beat {
            if render.effect_no_offset {
                let seconds = music(call, &clock)?;
                // The production fallback evaluates the runtime beat even if
                // timing data supplies the selected no-offset position.
                let fallback = values(call, false)?[0];
                clock.no_offset.as_ref().map_or(fallback, |timing| {
                    timing.get_song_position_no_offset(seconds).beat
                })
            } else {
                values(call, false)?[0]
            }
        } else {
            music(call, &clock)?
        };
        (units, units - previous)
    };
    let mut store = store.lock().unwrap();
    let actor = store.actors.get_mut(&actor).unwrap();
    actor.effects.motion = Some(Motion {
        units: Some(units),
        delta: elapsed,
    });
    if actor.effects.spin_seen {
        if actor.state.render.effect_mode == EffectMode::Spin {
            let magnitude = actor.state.render.effect_magnitude;
            for (angle, speed) in [
                &mut actor.current.rot_x_deg,
                &mut actor.current.rot_y_deg,
                &mut actor.current.rot_z_deg,
            ]
            .into_iter()
            .zip(magnitude)
            {
                *angle = (*angle + elapsed * speed).rem_euclid(360.0);
            }
        }
        actor.effects.spin_baked = true;
    }
    Ok(())
}

pub(super) fn render_time(actor: &Actor, frame_clock: [f32; 2], render: &mut SongLuaOverlayState) {
    render.spin_baked = actor.effects.spin_baked;
    if (render.rainbow || !matches!(render.effect_mode, EffectMode::None | EffectMode::Spin))
        && let Some(motion) = actor.effects.motion
    {
        render.effect_time = Some([
            frame_clock[usize::from(render.effect_clock == EffectClock::Beat)],
            motion.units.unwrap_or(0.0),
        ]);
    }
}
